package com.fuelflex.platform.reception.dto;
import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.*; import com.fuelflex.platform.reception.model.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*;
public final class ReceptionDtos { private ReceptionDtos(){} public record ReceptionItemRequest(@NotNull UUID purchaseOrderItemId,@NotNull @DecimalMin(value="0.0",inclusive=false) @Digits(integer=16,fraction=3) BigDecimal receivedQuantity,@NotNull @DecimalMin(value="0.0",inclusive=false) @Digits(integer=16,fraction=4) BigDecimal purchaseUnitPrice,@Size(max=3) String currency,@Size(max=2000) String observation,List<@Valid ReceptionTankAllocationRequest> allocations){} public record ReceptionTankAllocationRequest(@NotNull UUID tankId,@NotNull @DecimalMin(value="0.0",inclusive=false) @Digits(integer=16,fraction=3) BigDecimal quantity){} public record ReceptionCreateRequest(@NotNull UUID purchaseOrderId,@Size(max=100) String deliveryNoteNumber,OffsetDateTime deliveryDate,@Size(max=2000) String generalObservation,@NotEmpty List<@Valid ReceptionItemRequest> items){} public record ReceptionUpdateRequest(@Size(max=100) String deliveryNoteNumber,OffsetDateTime deliveryDate,@Size(max=2000) String generalObservation,@NotEmpty List<@Valid ReceptionItemRequest> items){} public record ReceptionSubmitRequest(@Size(max=1000) String comment){} public record SupervisorReceptionDecisionRequest(@Size(max=1000) String comment){} public record UserSummary(UUID id,String firstName,String lastName){} public record ItemResponse(UUID id,UUID purchaseOrderItemId,UUID productId,String productName,BigDecimal orderedQuantitySnapshot,BigDecimal previouslyReceivedQuantity,BigDecimal backlogBeforeReception,BigDecimal receivedQuantity,BigDecimal purchaseUnitPrice,String currency,BigDecimal differenceQuantity,String observation,List<AllocationResponse> allocations){} public record AllocationResponse(UUID id,UUID tankId,String tankName,BigDecimal quantity){} public record Response(UUID id,String receptionNumber,UUID purchaseOrderId,String purchaseOrderNumber,UUID stationId,String stationName,ReceptionStatus status,String deliveryNoteNumber,OffsetDateTime deliveryDate,String generalObservation,UserSummary createdBy,OffsetDateTime createdAt,OffsetDateTime updatedAt,OffsetDateTime submittedAt,UserSummary supervisorReviewedBy,OffsetDateTime supervisorReviewedAt,String supervisorComment,List<ItemResponse> items){} public record ReceivableOrderItemResponse(UUID purchaseOrderItemId,UUID productId,String productName,String unit,BigDecimal orderedQuantity,BigDecimal validatedQuantity,BigDecimal remainingQuantity){} public record ReceivableOrderResponse(UUID purchaseOrderId,String purchaseOrderNumber,UUID stationId,String stationName,String supplierName,com.fuelflex.platform.purchaseorder.model.PurchaseOrderStatus status,List<ReceivableOrderItemResponse> items){} public record StockBalanceResponse(UUID stationId,String stationName,UUID tankId,String tankName,UUID productId,String productName,BigDecimal capacity,BigDecimal currentStock,BigDecimal availableCapacity,BigDecimal fillPercentage){} public record HistoryResponse(UUID id,ReceptionHistoryAction action,ReceptionStatus oldStatus,ReceptionStatus newStatus,UserSummary performedBy,OffsetDateTime performedAt,String comment){} }
